(async()=>{const select=document.getElementById('football-year'),output=document.getElementById('football-values'),metric=document.getElementById('football-metric'),container=document.getElementById('football-chart'),detail=document.getElementById('football-chart-detail');try{const response=await fetch('assets/project-charts.json');if(!response.ok)throw Error();const {finance}=await response.json();const rows=finance.map((r,i)=>({...r,growth:i?(r.revenue/finance[i-1].revenue-1)*100:null}));const format=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:1});const money=v=>format.format(v)+'m';rows.forEach(row=>{const option=document.createElement('option');option.value=row.year;option.textContent=row.year;select.append(option);});function renderYear(){const row=rows.find(r=>String(r.year)===select.value);output.textContent=row.year+' · Revenue: '+money(row.revenue)+' · Annual result: '+money(row.loss)+(row.growth===null?' · Prior-year change unavailable.':' · Revenue change: '+row.growth.toFixed(1)+'%.');}select.value=String(rows.at(-1).year);select.addEventListener('change',()=>{renderYear();draw();});renderYear();
const ns='http://www.w3.org/2000/svg';function svgEl(tag,attrs={},text){const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n;}
function draw(){const mode=metric.value,isGrowth=mode==='growth',series=mode==='both'?['revenue','loss']:[mode];const colors={revenue:'#345eea',loss:'#b74759',growth:'#207964'},names={revenue:'Revenue',loss:'Annual result',growth:'Revenue change'};const vals=rows.flatMap(r=>series.map(k=>r[k])).filter(v=>v!==null);let lo=Math.min(0,...vals),hi=Math.max(0,...vals),pad=(hi-lo)*.1||1;lo-=pad;hi+=pad;const x=i=>85+i*175,y=v=>315-(v-lo)/(hi-lo)*255;const svg=svgEl('svg',{viewBox:'0 0 850 390',role:'img','aria-label':isGrowth?'Year-on-year revenue change, 2021 to 2024':series.map(k=>names[k]).join(' and ')+', 2020 to 2024, million pounds'});svg.append(svgEl('text',{x:85,y:25},isGrowth?'Revenue change (%)':'£ million · historical observations'));for(let j=0;j<=4;j++){const v=lo+(hi-lo)*j/4,yy=y(v);svg.append(svgEl('line',{x1:85,x2:785,y1:yy,y2:yy,stroke:'#dce1d7'}),svgEl('text',{x:72,y:yy+4,'text-anchor':'end'},v.toFixed(isGrowth?1:0)));}svg.append(svgEl('line',{x1:85,x2:785,y1:y(0),y2:y(0),stroke:'#7b897d','stroke-dasharray':'4 4'}));rows.forEach((r,i)=>svg.append(svgEl('text',{x:x(i),y:348,'text-anchor':'middle'},r.year)));series.forEach(key=>{const points=rows.map((r,i)=>r[key]===null?null:[x(i),y(r[key])]).filter(Boolean);if(!isGrowth)svg.append(svgEl('polyline',{points:points.map(p=>p.join(',')).join(' '),fill:'none',stroke:colors[key],'stroke-width':3}));rows.forEach((r,i)=>{if(r[key]===null)return;const txt=r.year+' · '+names[key]+': '+(isGrowth?r[key].toFixed(1)+'%':money(r[key]))+'. Observed history; not a forecast.';const point=isGrowth?svgEl('rect',{x:x(i)-23,y:Math.min(y(0),y(r[key])),width:46,height:Math.max(2,Math.abs(y(r[key])-y(0))),rx:3,fill:colors[key],tabindex:0,role:'button','aria-label':txt}):svgEl('circle',{cx:x(i),cy:y(r[key]),r:String(r.year)===select.value?8:6,fill:colors[key],stroke:'#fff','stroke-width':2,tabindex:0,role:'button','aria-label':txt});point.append(svgEl('title',{},txt));const inspect=()=>{detail.textContent=txt;};const choose=()=>{select.value=String(r.year);renderYear();detail.textContent=txt;};point.addEventListener('mouseenter',inspect);point.addEventListener('focus',inspect);point.addEventListener('click',choose);point.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});svg.append(point);});});const legend=document.createElement('div');legend.className='football-legend';series.forEach(key=>{const span=document.createElement('span');span.style.setProperty('--series',colors[key]);span.textContent=names[key];legend.append(span);});container.replaceChildren(legend,svg);detail.textContent=isGrowth?'Select a bar to inspect the year-on-year change. 2020 has no preceding observation.':'Hover or keyboard-focus a point; select it to inspect that financial year. Both series use the same £ million axis.';}
metric.addEventListener('change',draw);draw();}catch{output.textContent='Historical figures could not be loaded. Please reload the page.';}})();
